// 3 days/week, ~45 min sessions, moderate intensity. Equipment: Dual adjustable pulley (cable), Lat pulldown station.
# Week 1
// Estimated ~42 min
## Full Body A
// Arms forward for balance, full depth you can control.
Squat, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Pulleys at chest height, step forward, press handles together.
Bench Press, Cable / 3x8 / 10kg / 120s / progress: dp(2.5kg, 8, 12)
// Low pulley, sit tall, pull handles to your ribs.
Seated Row, Cable / 3x8 / 20kg / 120s / progress: dp(2.5kg, 8, 12)
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Low pulley, elbows still, squeeze at the top.
Bicep Curl, Cable / 3x10 / 7.5kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Low pulley across your body, raise out to the side.
Lateral Raise, Cable / 3x10 / 5kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)

// Estimated ~41 min
## Full Body B
// Low pulley with rope, face away, hinge and squeeze glutes.
Cable Pull Through, Cable / 3x8 / 15kg / 120s / progress: dp(2.5kg, 8, 12)
// Low pulleys, sit or kneel between them, press overhead.
Shoulder Press, Cable / 3x8 / 7.5kg / 120s / progress: dp(2.5kg, 8, 12)
// Thighs under the pad, pull the bar to your upper chest.
Lat Pulldown, Cable / 3x8 / 25kg / 120s / progress: dp(2.5kg, 8, 12)
// Hold handles from the low pulleys, step back.
Reverse Lunge, Cable / 3x10 / 10kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Elbows pinned, push the bar/rope down to full lockout.
Triceps Pushdown, Cable / 3x10 / 15kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)

// Estimated ~43 min
## Full Body C
// Arms forward for balance, full depth you can control.
Squat, Bodyweight / 3x8 / 0kg / 75s / warmup: none
// Body in one straight line, chest to just above the floor.
Push Up, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Low pulley, sit tall, pull handles to your ribs.
Seated Row, Cable / 3x8 / 20kg / 120s
// Ankle strap on the low pulley, kick back without arching.
Glute Kickback, Cable / 3x10 / 5kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Kneel with the rope, crunch ribs toward hips.
Cable Crunch, Cable / 3x10 / 15kg / 75s / warmup: none / progress: dp(2.5kg, 10, 14)
// Low pulley, elbows still, squeeze at the top.
Bicep Curl, Cable / 3x10 / 7.5kg / 75s / warmup: none
// Hands together under your chest, elbows close.
Diamond Push Up, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
